package com.bomboniere.estoque.controller;
import com.bomboniere.estoque.dto.*; import com.bomboniere.estoque.service.CategoriaService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/categorias")
public class CategoriaController { private final CategoriaService service; public CategoriaController(CategoriaService s){service=s;} @GetMapping public List<CategoriaResponse> listar(){return service.listar();} @GetMapping("/{id}") public CategoriaResponse buscar(@PathVariable Long id){return service.buscar(id);} @PostMapping public ResponseEntity<CategoriaResponse> criar(@Valid @RequestBody CategoriaRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.criar(r));} @PutMapping("/{id}") public CategoriaResponse atualizar(@PathVariable Long id,@Valid @RequestBody CategoriaRequest r){return service.atualizar(id,r);}@DeleteMapping("/{id}") public ResponseEntity<Void> excluir(@PathVariable Long id){service.excluir(id);return ResponseEntity.noContent().build();} }
